+import { Heart, Droplet, Star, Coins } from "lucide-react";
+import characterPortrait from "@/assets/character-portrait.png";
+import { Progress } from "@/components/ui/progress";
+
+interface PlayerPanelProps {
+  character: {
+    name: string;
+    level: number;
+    hp: number;
+    maxHp: number;
+    mana: number;
+    maxMana: number;
+    xp: number;
+    xpToNextLevel: number;
+    gold: number;
+  };
+}
